class TimeMap {
  private hist = new Map<string, [number, string][]>();

  set(key: string, value: string, timestamp: number): void {
    if (!this.hist.has(key)) this.hist.set(key, []);
    this.hist.get(key)!.push([timestamp, value]);
  }

  get(key: string, timestamp: number): string {
    const h = this.hist.get(key) ?? [];
    for (let i = h.length - 1; i >= 0; i--) if (h[i][0] <= timestamp) return h[i][1];
    return "";
  }
}

