class TimeMap {
  private times = new Map<string, number[]>();
  private values = new Map<string, string[]>();

  set(key: string, value: string, timestamp: number): void {
    if (!this.times.has(key)) { this.times.set(key, []); this.values.set(key, []); }
    this.times.get(key)!.push(timestamp);
    this.values.get(key)!.push(value);
  }

  get(key: string, timestamp: number): string {
    const ts = this.times.get(key);
    if (!ts) return "";
    let lo = 0, hi = ts.length; // find the first time > timestamp in [lo, hi)
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (ts[mid] <= timestamp) lo = mid + 1;
      else hi = mid;
    }
    return lo === 0 ? "" : this.values.get(key)![lo - 1];
  }
}

